const $=s=>document.querySelector(s),node=(tag,text='',cls='')=>{const el=document.createElement(tag);el.textContent=text;el.className=cls;return el;};let admin=false,rows=[],draft=null;
const isVideo=file=>['video/mp4','video/webm'].includes(file.type)||/\.(mp4|webm)$/i.test(file.name);
async function api(path='',method='GET',body,token){const r=await fetch('/api/bricos'+path,{method,cache:'no-store',headers:{...(body&&!(body instanceof FormData)?{'Content-Type':'application/json'}:{}),...(token?{'X-Upload-Token':token}:{})},...(body?{body:body instanceof FormData?body:JSON.stringify(body)}:{})});const data=await r.json();if(!r.ok)throw Error(data.error||'No se pudo completar la operación.');return data;}
function button(label,action){const b=node('button',label);b.type='button';b.onclick=async()=>{try{await action();}catch(error){$('[data-brico-status]').textContent=error.message;}};return b;}
async function load(){rows=await api();const grid=$('[data-brico-list]');grid.replaceChildren();for(const row of rows){const card=node('article','','brico-card');card.append(node('p',row.category+' · '+row.vehicle,'eyebrow red'),node('h3',row.title),node('p','Por '+row.author));card.append(button('Ver tutorial →',()=>void open(row.id)));grid.append(card);}$('[data-brico-status]').textContent=rows.length?rows.length+' tutoriales publicados.':'Todavía no hay tutoriales publicados. ¡Comparte el primero!';if(admin)await reviews();}
async function open(id){try{const row=await api('/'+encodeURIComponent(id)),root=$('[data-brico-detail]');root.hidden=false;root.replaceChildren(node('p',row.category+' · '+row.vehicle,'eyebrow red'),node('h2',row.title),node('p','Tutorial de '+row.author),node('div',row.steps,'brico-steps'));const media=node('div','','brico-media');for(const item of row.media){const figure=node('figure');if(item.content_type.startsWith('video/')){const video=node('video');video.src=item.url;video.controls=true;video.playsInline=true;video.preload='metadata';figure.append(video);}else{const image=node('img');image.src=item.url;image.alt=item.caption||'Foto del tutorial';image.loading='lazy';const b=button(' ',()=>{const d=$('[data-brico-lightbox]');d.querySelector('img').src=item.url;d.showModal();});b.setAttribute('aria-label','Ampliar fotografía');b.replaceChildren(image);figure.append(b);}if(item.caption)figure.append(node('figcaption',item.caption));if(admin&&row.status==='approved')figure.append(button('Eliminar archivo',async()=>{if(!confirm('¿Eliminar este archivo del brico?'))return;await api('/'+id+'/media/'+item.id,'DELETE');await open(id);}));media.append(figure);}root.append(media);if(admin&&row.status==='approved')root.append(adminEditor(row));root.append(node('h3','Comentarios y consejos'));for(const comment of row.comments){const article=node('article','','brico-comment');article.append(node('strong',comment.author),node('p',comment.body));if(admin&&comment.status!=='approved'){article.append(node('p',comment.status==='pending'?'Pendiente de revisión':'Comentario rechazado'),button('Aprobar comentario',async()=>{await api('/comments/'+comment.id,'POST',{status:'approved'});await open(id);}),button('Rechazar comentario',async()=>{await api('/comments/'+comment.id,'POST',{status:'rejected'});await open(id);}));}root.append(article);}if(row.status==='approved'){const form=node('form','','club-form');const name=node('input'),body=node('textarea'),consent=node('input'),status=node('p');name.name='author';name.required=true;name.minLength=2;name.maxLength=80;name.placeholder='Tu nombre o alias';name.setAttribute('aria-label','Tu nombre o alias');body.name='body';body.required=true;body.minLength=2;body.maxLength=2000;body.placeholder='Tu comentario o consejo';body.setAttribute('aria-label','Comentario');consent.type='checkbox';consent.required=true;const label=node('label','Acepto publicar mi comentario tras revisión. ');label.prepend(consent);const send=node('button','Enviar comentario a revisión','button');send.type='submit';status.setAttribute('role','status');form.append(name,body,label,send,status);form.onsubmit=async event=>{event.preventDefault();send.disabled=true;try{await api('/'+id+'/comments','POST',{author:name.value,body:body.value,consent:consent.checked});form.reset();status.textContent='Comentario enviado. Está pendiente de revisión.';}catch(error){status.textContent=error.message;}finally{send.disabled=false;}};root.append(form);}history.replaceState(null,'','bricos.html?tutorial='+encodeURIComponent(id));root.scrollIntoView({behavior:'instant',block:'start'});root.focus({preventScroll:true});}catch(error){$('[data-brico-status]').textContent=error.message;}}
function adminEditor(row){const form=node('form','','club-form brico-admin-editor'),status=node('p');status.setAttribute('role','status');const field=(label,name,value,type='text')=>{const wrap=node('label',label),input=node(type);input.name=name;input.value=value||'';input.required=true;if(name==='title')input.maxLength=160;if(name==='author')input.maxLength=80;if(name==='vehicle')input.maxLength=120;wrap.append(input);return wrap;};form.append(node('h3','Editar brico publicado'),field('Título','title',row.title),field('Autor o alias','author',row.author),field('Modelo y año','vehicle',row.vehicle));const categoryWrap=node('label','Temática'),category=node('select');category.name='category';for(const value of ['Mantenimiento','Interior','Exterior','Electrónica','Mecánica','Otros']){const option=node('option',value);option.value=value;category.append(option);}if(![...category.options].some(option=>option.value===row.category)){const option=node('option',row.category);option.value=row.category;category.append(option);}category.value=row.category;categoryWrap.append(category);form.append(categoryWrap);const stepsWrap=node('label','Pasos del tutorial'),steps=node('textarea');steps.name='steps';steps.rows=9;steps.minLength=20;steps.maxLength=12000;steps.required=true;steps.value=row.steps;stepsWrap.append(steps);form.append(stepsWrap);const filesWrap=node('label','Añadir fotos o vídeos'),files=node('input');files.type='file';files.name='files';files.multiple=true;files.accept='image/jpeg,image/png,image/webp,video/mp4,video/webm';filesWrap.append(files);form.append(filesWrap,node('p','Puedes añadir archivos nuevos o eliminar los actuales con el botón de cada uno. Máximo 10 archivos por brico.'),button('Guardar cambios',()=>{}));const save=form.querySelector('button');save.type='submit';save.onclick=null;form.append(status);form.onsubmit=async event=>{event.preventDefault();const additions=[...files.files];if(row.media.length+additions.length>10){status.textContent='El brico admite como máximo 10 archivos.';return;}if(additions.some(file=>(!['image/jpeg','image/png','image/webp'].includes(file.type)&&!isVideo(file))||file.size>25*1024*1024)){status.textContent='Revisa los formatos y el límite de 25 MB por archivo.';return;}save.disabled=true;let textSaved=false;try{await api('/'+row.id+'/edit','POST',{title:form.elements.title.value,author:form.elements.author.value,vehicle:form.elements.vehicle.value,category:category.value,steps:steps.value});textSaved=true;for(const file of additions){const data=new FormData();data.set('file',isVideo(file)?file:await imageBlob(file),isVideo(file)?file.name:'brico.jpg');await api('/'+row.id+'/media','POST',data);}await load();await open(row.id);$('[data-brico-status]').textContent='Brico actualizado.';}catch(error){const message=error.message;await load();await open(row.id);$('[data-brico-status]').textContent=(textSaved?'El texto se guardó, pero no se pudieron guardar todos los archivos: ':'No se pudieron guardar los cambios: ')+message;}finally{save.disabled=false;}};return form;}
async function reviews(){const list=await api('?manage=1'),filter=$('[data-brico-review-filter]').value,root=$('[data-brico-review-list]');root.replaceChildren();for(const row of list.filter(r=>r.status===filter)){const card=node('article','','brico-card');card.append(node('h3',row.title),node('p',row.author+' · '+row.vehicle),node('p',row.review_note));card.append(button('Ver texto y archivos',()=>void open(row.id)));if(row.status==='approved')card.append(button('Editar brico publicado',()=>void open(row.id)));for(const [state,label]of [['approved','Aprobar y publicar'],['rejected','Rechazar / retirar']]){card.append(button(label,async()=>{const note=prompt('Nota de revisión (opcional)','');if(note===null)return;try{await api('/'+row.id+'/review','POST',{status:state,note});await load();}catch(error){$('[data-brico-status]').textContent=error.message;}}));}card.append(button('Eliminar definitivamente',async()=>{if(!confirm('¿Eliminar este tutorial y todos sus archivos?'))return;await api('/'+row.id,'DELETE');await load();}));root.append(card);}if(!root.children.length)root.append(node('p','No hay tutoriales en este estado.'));}
async function imageBlob(file){if(file.size>20*1024*1024)throw Error('La foto supera 20 MB.');const image=await createImageBitmap(file),ratio=Math.min(1,1600/Math.max(image.width,image.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*ratio));canvas.height=Math.max(1,Math.round(image.height*ratio));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);image.close();for(const q of [.85,.7,.5,.3]){const blob=await new Promise(r=>canvas.toBlob(r,'image/jpeg',q));if(blob?.size<=1048576)return blob;}throw Error('No se pudo reducir la foto.');}
$('[data-brico-form]').onsubmit=async event=>{event.preventDefault();const form=event.currentTarget,send=form.querySelector('button[type=submit]'),status=$('[data-brico-save]'),files=[...form.elements.files.files];if(files.length>10){status.textContent='Selecciona como máximo 10 archivos.';return;}if(files.some(f=>(!['image/jpeg','image/png','image/webp'].includes(f.type)&&!isVideo(f))||f.size>25*1024*1024)){status.textContent='Revisa los formatos y el límite de 25 MB.';return;}send.disabled=true;try{if(!draft){draft=await api('','POST',Object.fromEntries(new FormData(form)));draft.uploaded=0;form.querySelectorAll('input:not([name=consent]),select,textarea').forEach(el=>el.disabled=true);}for(let i=draft.uploaded;i<files.length;i++){status.textContent='Subiendo archivo '+(i+1)+' de '+files.length+'…';const data=new FormData(),file=files[i];data.set('file',isVideo(file)?file:await imageBlob(file),isVideo(file)?file.name:'brico.jpg');await api('/'+draft.id+'/media','POST',data,draft.uploadToken);draft.uploaded=i+1;}await api('/'+draft.id+'/submit','POST',{consent:form.elements.consent.checked},draft.uploadToken);draft=null;form.querySelectorAll('input,select,textarea').forEach(el=>el.disabled=false);form.reset();status.textContent='Tutorial enviado. Pendiente de revisión por los administradores.';if(admin)await reviews();}catch(error){status.textContent=error.message+' Puedes volver a pulsar para reintentar el envío.';}finally{send.disabled=false;}};
$('[data-brico-review-filter]').onchange=()=>void reviews();$('[data-brico-close]').onclick=()=>$('[data-brico-lightbox]').close();try{admin=(await fetch('/api/admin/session',{cache:'no-store'})).ok;}catch{}$('[data-brico-reviews]').hidden=!admin;$('[data-brico-review-link]').hidden=!admin;try{await load();const id=new URLSearchParams(location.search).get('tutorial');if(id)await open(id);}catch(error){$('[data-brico-status]').textContent=error.message;}
